using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BNPlay {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-10_B2_DomeNetwork/";
 static GameObject player;static PlayerMotor motor;static PlayerLook look;static Transform pivot;static CharacterController cc;static Vector3 savedPos,from;static Quaternion savedRot,savedPitch;static bool savedLook,running;static int stage,first,last;static float startTime;static double wallStart;static List<object> rows=new List<object>();static List<string> errors=new List<string>();static InputSettings.BackgroundBehavior bg;static InputSettings.EditorInputBehaviorInPlayMode eb;static bool standBlocked;static float maxRise,minRise;static int moveEvents;static InputAction move;
 static Vector3 At(JToken t,float d){var ps=t["path"].Select(p=>new Vector3((float)p[0],-34,-(float)p[1])).ToList();for(int i=1;i<ps.Count;i++){float len=Vector3.Distance(ps[i-1],ps[i]);if(d<=len)return Vector3.Lerp(ps[i-1],ps[i],d/len);d-=len;}return ps.Last();}
 public static object Prepare(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");SessionState.SetBool("BNPlay.Background",Application.runInBackground);Application.runInBackground=true;return new{mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled};}
 public static object Begin(){if(!Application.isPlaying||!SceneManager.GetActiveScene().path.EndsWith("Level_B2_Circular.unity"))throw new Exception("B2 Play required");player=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));motor=player.GetComponent<PlayerMotor>();look=player.GetComponent<PlayerLook>();cc=player.GetComponent<CharacterController>();pivot=(Transform)typeof(PlayerLook).GetField("cameraRoot",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(look);savedPos=player.transform.position;savedRot=player.transform.rotation;savedPitch=pivot.localRotation;savedLook=look.enabled;look.enabled=false;pivot.localRotation=Quaternion.identity;bg=InputSystem.settings.backgroundBehavior;eb=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();rows.Clear();errors.Clear();moveEvents=0;move=player.GetComponent<PlayerInput>().actions.FindAction("Player/Move",true);move.performed+=ReadMove;stage=0;running=true;Next();InputSystem.onAfterUpdate+=Input;EditorApplication.update+=Tick;Application.logMessageReceived+=Log;AssemblyReloadEvents.beforeAssemblyReload+=Cancel;EditorApplication.playModeStateChanged+=Mode;return new{started=true,stages=4,frame=Time.frameCount};}
 static void ReadMove(InputAction.CallbackContext c){moveEvents++;}static void Log(string m,string st,LogType t){if(t==LogType.Error||t==LogType.Exception)errors.Add(m);}static void Mode(PlayModeStateChange m){if(m==PlayModeStateChange.ExitingPlayMode)Cancel();}static void Cancel(){if(running)End(false);}
 static void Next(){
 var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_DetailMezzanine/layout.json"));var t=plan["tunnels"].Single(p=>(string)p["id"]=="T14");float len=(float)t["length"];var ground=At(t,1);cc.enabled=false;player.transform.position=ground+Vector3.up*(cc.height/2-cc.center.y+.03f);cc.enabled=true;Physics.SyncTransforms();motor.TryStandUp();if(stage==0||stage==2)motor.Crouch();Vector3 pos,dir;
 if(stage==0){pos=At(t,len-1)+Vector3.up*2.42f;dir=(At(t,len)-At(t,len-.1f)).normalized;}
 else if(stage==1){pos=new Vector3(121.8f,-34,1.75f);dir=Vector3.forward;}
 else if(stage==2){var data=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_DomeNetwork/layout.json"));var r=data["rooms"].Single(v=>(string)v["id"]=="E02");var d=r["doors"].Single(v=>(string)v["id"]=="B2-T16");dir=new Vector3((float)d["x"],0,(float)d["z"]).normalized;pos=new Vector3(124,-30.4f,5)+dir*5.55f;}
 else{pos=At(t,2);dir=(At(t,2.1f)-At(t,2)).normalized;pos+=Vector3.Cross(Vector3.up,dir)*1.3f;}
 cc.enabled=false;player.transform.SetPositionAndRotation(pos+Vector3.up*(cc.height/2-cc.center.y+.025f),Quaternion.LookRotation(dir));cc.enabled=true;Physics.SyncTransforms();typeof(PlayerMotor).GetField("verticalVelocity",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(motor,0f);from=player.transform.position;first=last=Time.frameCount;startTime=Time.time;wallStart=EditorApplication.timeSinceStartup;standBlocked=false;maxRise=minRise=0;
 }
 static void Input(){if(running&&InputState.currentUpdateType!=InputUpdateType.Editor){float t=Time.time-startTime;InputState.Change(Keyboard.current,t>.25f&&t<3.05f?new KeyboardState(Key.W):new KeyboardState());}}
 static void Tick(){try{if(!Application.isPlaying){End(false);return;}EditorApplication.QueuePlayerLoopUpdate();float elapsed=Time.time-startTime;if(Time.frameCount!=last){last=Time.frameCount;float rise=player.transform.position.y-from.y;maxRise=Mathf.Max(maxRise,rise);minRise=Mathf.Min(minRise,rise);if(stage==0&&elapsed>.30f&&!standBlocked)standBlocked=!motor.TryStandUp();}if(elapsed<3.8f&&EditorApplication.timeSinceStartup-wallStart<25)return;var delta=player.transform.position-from;float dist=new Vector2(delta.x,delta.z).magnitude;bool pass=Time.frameCount-first>20&&dist>3&&errors.Count==0&&(stage!=0||(standBlocked&&delta.y>1.0f))&&(stage!=1||delta.y>2.4f)&&(stage!=2||delta.y<-.95f)&&(stage!=3||Mathf.Abs(delta.y)<.15f);rows.Add(new{stage,name=new[]{"T14 crouch portal into E01 deck","E02 interior stair ascent","E02 descent into T16 upper","T14 lower standing bypass"}[stage],passed=pass,frames=Time.frameCount-first,distance=dist,rise=delta.y,maxRise,minRise,crouching=motor.IsCrouching,standBlocked,grounded=cc.isGrounded,moveEvents});stage++;if(stage<4)Next();else End(true);}catch(Exception e){errors.Add(e.ToString());End(false);}}
 static void End(bool complete){running=false;InputSystem.onAfterUpdate-=Input;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;AssemblyReloadEvents.beforeAssemblyReload-=Cancel;EditorApplication.playModeStateChanged-=Mode;if(move!=null)move.performed-=ReadMove;try{InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());File.WriteAllText(O+"play.json",JsonConvert.SerializeObject(new{complete,results=rows,errors,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled},Formatting.Indented));}finally{InputSystem.settings.backgroundBehavior=bg;InputSystem.settings.editorInputBehaviorInPlayMode=eb;if(player){cc.enabled=false;player.transform.SetPositionAndRotation(savedPos,savedRot);cc.enabled=true;motor.TryStandUp();}if(pivot)pivot.localRotation=savedPitch;if(look)look.enabled=savedLook;}}
 public static object Restore(){if(Application.isPlaying)throw new Exception("Exit Play first");Application.runInBackground=SessionState.GetBool("BNPlay.Background",false);return new{mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,Application.runInBackground,dirty=SceneManager.GetActiveScene().isDirty};}
}
